"""Constants for MCP server."""

from pathlib import Path
from typing import Literal

from rasa.core.constants import DEFAULT_SERVER_PORT

# Default Rasa server URL used when no explicit URL is configured.
# Must match DEFAULT_SERVER_PORT in rasa/core/constants.py.
DEFAULT_RASA_SERVER_URL = f"http://localhost:{DEFAULT_SERVER_PORT}"

INSTRUCTIONS_FILE_PATH = Path(__file__).parent / "INSTRUCTIONS.md"

# MCP Transport Modes
MCP_TRANSPORT_STDIO: Literal["stdio"] = "stdio"
MCP_TRANSPORT_STREAMABLE_HTTP: Literal["streamable-http"] = "streamable-http"

# MCP Server Configuration
MCP_DEFAULT_HOST = "127.0.0.1"
MCP_DEFAULT_PORT = 5051  # Used by builder mode (embedded server)
MCP_TOOLS_DEFAULT_PORT = 7331  # Used by `rasa tools run` (standalone server)
MCP_HTTP_URL_PATTERN = "http://{host}:{port}/mcp"
MCP_HTTP_HEALTH_URL_PATTERN = "http://{host}:{port}/health"

# MCP Tool Names - Centralized constants for tool names used throughout the codebase
# These are Rasa-specific tools exposed via the MCP server
MCP_TOOL_VALIDATE_PROJECT = "validate_project"
MCP_TOOL_TRAIN_RASA_ASSISTANT = "train_rasa_assistant"
MCP_TOOL_GET_ASSISTANT_LOGS = "get_assistant_logs"
MCP_TOOL_TALK_TO_ASSISTANT = "talk_to_assistant"
MCP_TOOL_LIST_CUSTOM_ACTION_IMPLEMENTATIONS = "list_custom_action_implementations"

# Project context tools - for listing flows, slots, responses, and custom actions
MCP_TOOL_LIST_FLOWS = "list_project_flow_definitions"
MCP_TOOL_LIST_SLOTS = "list_project_slot_definitions"
MCP_TOOL_LIST_RESPONSES = "list_project_response_definitions"
MCP_TOOL_LIST_DOMAIN_ACTIONS = "list_project_custom_actions_in_domain"
MCP_TOOL_LIST_DEFAULT_ACTIONS = "list_default_action_names"

# Granular getters - retrieve single flow/slot/response by identifier
MCP_TOOL_GET_FLOW = "get_flow"
MCP_TOOL_GET_SLOT = "get_slot"
MCP_TOOL_GET_RESPONSE = "get_response"

# Schema tools - expose Rasa schemas for validation and code generation
MCP_TOOL_GET_FLOW_SCHEMA = "get_flow_schema"
MCP_TOOL_GET_DOMAIN_SCHEMA = "get_domain_schema"
MCP_TOOL_GET_E2E_SCHEMA = "get_e2e_schema"

# Eval suite tools
MCP_TOOL_EVALUATE_AGENT = "evaluate_agent"
MCP_TOOL_VALIDATE_SCENARIO = "validate_scenario"

# `_meta` key naming the agent a tool call acts on, read from the current
# call's request context when the server serves a workspaces root rather than
# a single project folder.
MCP_META_AGENT_ID = "agent_id"

# `_meta` key naming the branch of that agent a tool call acts on. Optional:
# without it the call acts on the agent's `main` checkout.
MCP_META_BRANCH = "branch"

# Tool names bound to CALM-v1 mechanics (flows/slots/domain files, endpoints.yml
# actions discovery). Mantle (CALM v2 skill-based) projects have none of these
# concepts, so these tools are hidden for them. Kept in a set (not a loop over
# @mcp.tool call sites) so the gate is a single, auditable list.
MCP_V1_ONLY_TOOL_NAMES = frozenset(
    {
        MCP_TOOL_LIST_FLOWS,
        MCP_TOOL_LIST_SLOTS,
        MCP_TOOL_LIST_RESPONSES,
        MCP_TOOL_GET_FLOW,
        MCP_TOOL_GET_SLOT,
        MCP_TOOL_GET_RESPONSE,
        MCP_TOOL_LIST_DOMAIN_ACTIONS,
        MCP_TOOL_LIST_DEFAULT_ACTIONS,
        MCP_TOOL_GET_FLOW_SCHEMA,
        MCP_TOOL_GET_DOMAIN_SCHEMA,
        MCP_TOOL_GET_E2E_SCHEMA,
        MCP_TOOL_LIST_CUSTOM_ACTION_IMPLEMENTATIONS,
    }
)

# Tools that train, talk to, evaluate, or read the logs of an agent running in
# the builder process. The builder no longer runs one (Studio trains and serves
# the agent), so Copilot v2 never offers them (see `_offers_mcp_tool` in
# `rasa.builder.copilot.pydantic_ai.agent`).
MCP_IN_PROCESS_AGENT_TOOL_NAMES = frozenset(
    {
        MCP_TOOL_TRAIN_RASA_ASSISTANT,
        MCP_TOOL_TALK_TO_ASSISTANT,
        MCP_TOOL_EVALUATE_AGENT,
        MCP_TOOL_GET_ASSISTANT_LOGS,
    }
)

# Simulator & Evaluator constants
SIMULATOR_MAX_TURNS = 30
SIM_EVAL_LLM_MAX_ATTEMPTS = 3
# Bounds each (scenario, run) cell; run_scenarios derives the batch budget
# from this and the grid shape.
EVALUATE_AGENT_PER_RUN_TIMEOUT_S = 600
# Absolute ceiling on one evaluate_agent call. The derived batch budget grows
# with the grid, so without this a full batch could run for most of a day.
MAX_EVAL_BATCH_TIMEOUT_S = 2 * 60 * 60
# Conservative: a default `rasa run` is one Sanic worker, and one run is many
# LLM calls -- a simulation call per turn, the agent's own, then the judge.
DEFAULT_EVAL_PARALLELISM = 3
# Ceiling on the LLM-settable `parallelism`. Overshooting isn't self-correcting:
# retries are rate-limit-blind, and exhausting them reads as a failed run.
MAX_EVAL_PARALLELISM = 8
MAX_SCENARIOS_PER_BATCH = 50
# Per-role ceiling on concurrent provider calls, set in eval/conftest.yml.
# Never 1 -- that would make sequential execution the default again.
DEFAULT_MAX_CONCURRENT_LLM_CALLS = 3
# Backoff factor (seconds) between retry attempts.  Actual delay on
# attempt *n* is ``RETRY_BACKOFF_FACTOR * n``.
SIM_EVAL_RETRY_BACKOFF_FACTOR = 0.5
# Keys for the LLM conversation message dicts
LLM_ROLE = "role"
LLM_ROLE_SYSTEM = "system"
LLM_ROLE_ASSISTANT = "assistant"
LLM_ROLE_USER = "user"
LLM_MESSAGE_CONTENT = "content"
